185: /** Validate structural and trust-boundary constraints before reducing a message. */
186: export function validateA2uiMessage(value: unknown): A2uiValidationResult {
187:   const parsed = a2uiMessageSchema.safeParse(value);
188:   if (!parsed.success) return { success: false, error: parsed.error.issues[0]?.message ?? "Invalid A2UI message" };
189:   if (containsExecutableContent(parsed.data)) {
190:     return { success: false, error: "Executable HTML or JavaScript is not allowed in A2UI data" };
191:   }
192:   if ("updateComponents" in parsed.data) {
193:     const ids = parsed.data.updateComponents.components.map((component) => component.id);
194:     if (new Set(ids).size !== ids.length) {
195:       return { success: false, error: "A2UI component IDs must be unique within an update" };
196:     }
197:   }
